import{_ as a,o as i,c as e,ae as t}from"./chunks/framework.DQC_QtFV.js";const c=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1793162416000}'),l={name:"guide/quick-start.md"};function h(n,s,o,p,d,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>这一页把一个空机器带到&quot;面板能打开、二维码能扫&quot;。首次启动的细节（QQ 从哪来、 密钥怎么读）在 <a href="./first-start.html">首次启动与扫码登录</a>。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Linux x86_64，或在 Linux 虚拟机里运行的 macOS / Windows。</li><li>Docker 24+ 或 Podman 4+，带 <code>compose</code>。</li><li>约 2 GB 内存、5 GB 磁盘，用于镜像和客户端配置。</li><li>聊天后端的一个小号，不要用新号。</li><li>一个模型服务商的 API key（Anthropic、OpenAI、OpenRouter，或 pi 支持的任何一家）， 供模型使用。其余部分没有它也能跑。</li></ul><h2 id="四步起来" tabindex="-1">四步起来 <a class="header-anchor" href="#四步起来" aria-label="Permalink to &quot;四步起来&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/4fuu/personal-bot.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> personal-bot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>编辑 <code>.env</code>：设置 <code>CONSOLE_PASSWORD</code>，用 <code>openssl rand -hex 32</code> 生成三个令牌， 并选择一种 QQ 来源（见 <a href="./first-start.html">首次启动</a>）。每个变量的含义在 <a href="./env.html">环境变量</a> 里。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/driver/secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/bot/pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/bot/secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000:1000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/bot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>然后打开 <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a>，用 <code>CONSOLE_PASSWORD</code> 登录，在实时画面里用手机 App 扫码。勾选 自动登录，之后重启就能自己恢复。</p><div class="tip custom-block"><p class="custom-block-title">Rootless Podman</p><p>目录建好后执行一次 <code>podman unshare chown -R 1000:1000 data/bot workspace logs</code>，代替上面的 <code>sudo chown</code>。</p></div><h2 id="第一次登录要等一会儿" tabindex="-1">第一次登录要等一会儿 <a class="header-anchor" href="#第一次登录要等一会儿" aria-label="Permalink to &quot;第一次登录要等一会儿&quot;">​</a></h2><p>首次登录时，驱动程序要在调试器里从客户端读出数据库密钥：虚拟显示下首次启动实测最多 约 8 分钟。面板状态行显示 <code>db.key = &quot;ok&quot;</code> 时即完成，在那之前面板的机器人页面可能还在 报错，这是正常的。等待的上限由 <code>KEYX_TIMEOUT_S</code> 控制（默认 900 秒），超时不致命—— 驱动程序会继续等，密钥就绪后状态自己变成 <code>&quot;ok&quot;</code>。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>让模型开口：在 <a href="./console/conversations.html">会话</a> 里把至少一个会话设成 参与， 并在 <a href="./console/safety.html">安全</a> 里加一个管理员——两者齐备之前它不会开始任何一轮。</li><li>给它一个模型：在 <a href="./console/models.html">模型</a> 里登录服务商、选主模型。</li><li>想让它记住你：在 <a href="./console/persona.html">人设</a> 里写它是谁、怎么说话。</li></ul>`,14)])])}const F=a(l,[["render",h]]);export{c as __pageData,F as default};
